def test_valid_rows_are_accepted():
    """Every row generated from the schema has to satisfy it."""
    for index, row in enumerate(VALID_ROWS):
        validate(SCHEMA, row)


def test_boundary_rows_are_accepted():
    """Values sitting exactly on a declared limit are still valid."""
    for index, row in enumerate(BOUNDARY_ROWS):
        validate(SCHEMA, row["data"])


@pytest.mark.parametrize("case", NEGATIVE_CASES)
def test_negative_cases_are_rejected(case):
    """Each negative case has to break the schema it was derived from."""
    with pytest.raises(ValidationError) as excinfo:
        validate(SCHEMA, case["data"])
    expected = " %s: " % case["keyword"]
    assert expected in str(excinfo.value), (
        "expected the %r keyword to be reported for %r, got: %s"
        % (case["keyword"], case["property"], excinfo.value)
    )


def test_negative_cases_exist():
    """The generator has to cover the family of violations."""
    kinds = {case["kind"] for case in NEGATIVE_CASES}
    assert kinds, "no negative case was generated for orders"
